using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Linq;using System.Threading.Tasks;using System.Windows.Forms;
sealed partial class Companion {
 bool colourPicking;
 internal async void PickScreenColour(){if(colourPicking)return;colourPicking=true;bool restore=Visible&&!IsTabbed;Color? picked=null;try{if(restore)Hide();if(captureButton!=null)captureButton.Hide();await Task.Delay(180);Rectangle area=SystemInformation.VirtualScreen;using(var bitmap=ScreenShot(area))using(var picker=new ScreenColourPicker(bitmap,area)){picker.Surface=panel;picker.Ink=ink;picker.Edge=accent;picker.Font=Font;if(picker.ShowDialog()==DialogResult.OK){Color c=picker.Chosen;string hex=ScreenColourPicker.Hex(c);store.Pref.RecentColours=(new[]{hex}).Concat(store.Pref.RecentColours??new string[0]).Where(ScreenColourPicker.ValidHex).Distinct(StringComparer.OrdinalIgnoreCase).Take(12).ToArray();store.SavePrefs();picked=c;}}}catch(Exception e){Tell("Could not pick a colour: "+e.Message);}finally{colourPicking=false;if(restore)Show();if(captureButton!=null&&store.Pref.CaptureButton)captureButton.Show();}if(picked.HasValue&&!IsDisposed)ShowPickedColour(picked.Value);}
 internal void ShowPickedColour(Color first){var f=Dialog("Screen colour",480,390);var layout=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(8),FlowDirection=FlowDirection.TopDown,WrapContents=false};var swatch=new Panel{Width=380,Height=58};var value=new TextBox{Width=380,ReadOnly=true};var buttons=new FlowLayoutPanel{Width=380,Height=40};Color chosen=first;Action<Color> set=c=>{chosen=c;swatch.BackColor=c;value.Text=ScreenColourPicker.Hex(c)+"    RGB("+c.R+", "+c.G+", "+c.B+")";};foreach(string label in new[]{"Copy HEX","Copy RGB","Pick again"}){var b=new Button{Text=label,AutoSize=true};b.Click+=(s,e)=>{if(label=="Pick again"){f.Close();PickScreenColour();return;}try{Clipboard.SetText(label=="Copy HEX"?ScreenColourPicker.Hex(chosen):"rgb("+chosen.R+", "+chosen.G+", "+chosen.B+")");Tell("Colour copied");}catch{Tell("Clipboard is busy; select and copy the colour value.");}};buttons.Controls.Add(b);}var recent=new FlowLayoutPanel{Width=380,Height=70};foreach(string h in (store.Pref.RecentColours??new string[0]).Where(ScreenColourPicker.ValidHex).Take(12)){Color c=ColorTranslator.FromHtml(h);var b=new Button{Width=28,Height=28,BackColor=c,UseVisualStyleBackColor=false,AccessibleName=h};b.Click+=(s,e)=>set(c);recent.Controls.Add(b);}layout.Controls.Add(swatch);layout.Controls.Add(value);layout.Controls.Add(buttons);layout.Controls.Add(new Label{Text="Recent colours · click a swatch",AutoSize=true});layout.Controls.Add(recent);f.Controls.Add(layout);ThemeControls(f);set(first);foreach(Control b in recent.Controls)b.BackColor=ColorTranslator.FromHtml(b.AccessibleName);f.FormClosed+=(s,e)=>f.Dispose();if(Visible&&TopLevel)f.Show(this);else{f.ShowInTaskbar=true;f.Show();}f.BringToFront();f.Activate();}
}
sealed class ScreenColourPicker:Form {
 internal Color Surface=Color.FromArgb(34,38,42),Ink=Color.White,Edge=Color.Teal;readonly Bitmap desktop;readonly Rectangle area;Point sample;internal Color Chosen;
 internal ScreenColourPicker(Bitmap image,Rectangle bounds){desktop=image;area=bounds;FormBorderStyle=FormBorderStyle.None;StartPosition=FormStartPosition.Manual;Bounds=bounds;TopMost=true;ShowInTaskbar=false;AutoScaleMode=AutoScaleMode.None;DoubleBuffered=true;Cursor=Cursors.Cross;KeyPreview=true;sample=new Point(Math.Max(0,Math.Min(image.Width-1,Cursor.Position.X-bounds.X)),Math.Max(0,Math.Min(image.Height-1,Cursor.Position.Y-bounds.Y)));Text="Pick screen colour · click to select · Esc to cancel";AccessibleName=Text;}
 internal static string Hex(Color c){return "#"+c.R.ToString("X2")+c.G.ToString("X2")+c.B.ToString("X2");}
 internal static bool ValidHex(string s){return s!=null&&System.Text.RegularExpressions.Regex.IsMatch(s,@"\A#[0-9A-Fa-f]{6}\z");}
 protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);sample=new Point(Math.Max(0,Math.Min(desktop.Width-1,e.X)),Math.Max(0,Math.Min(desktop.Height-1,e.Y)));Invalidate();}
 protected override void OnMouseDown(MouseEventArgs e){if(e.Button==MouseButtons.Right){DialogResult=DialogResult.Cancel;Close();return;}if(e.Button==MouseButtons.Left){Chosen=desktop.GetPixel(Math.Max(0,Math.Min(desktop.Width-1,e.X)),Math.Max(0,Math.Min(desktop.Height-1,e.Y)));DialogResult=DialogResult.OK;Close();}}
 protected override bool ProcessCmdKey(ref Message m,Keys key){if(key==Keys.Escape){DialogResult=DialogResult.Cancel;Close();return true;}return base.ProcessCmdKey(ref m,key);}
 protected override void OnPaint(PaintEventArgs e){e.Graphics.DrawImageUnscaled(desktop,0,0);Rectangle monitor=Screen.FromPoint(new Point(sample.X+area.X,sample.Y+area.Y)).Bounds;int left=monitor.Left-area.Left,top=monitor.Top-area.Top;int x=Math.Max(left,Math.Min(sample.X+24,monitor.Right-area.Left-230)),y=Math.Max(top,Math.Min(sample.Y+24,monitor.Bottom-area.Top-160));var box=new Rectangle(x,y,224,150);using(var brush=new SolidBrush(Surface))e.Graphics.FillRectangle(brush,box);using(var pen=new Pen(Edge,2))e.Graphics.DrawRectangle(pen,box);e.Graphics.InterpolationMode=InterpolationMode.NearestNeighbor;e.Graphics.PixelOffsetMode=PixelOffsetMode.Half;for(int dy=-4;dy<=4;dy++)for(int dx=-4;dx<=4;dx++){int px=Math.Max(0,Math.Min(desktop.Width-1,sample.X+dx)),py=Math.Max(0,Math.Min(desktop.Height-1,sample.Y+dy));using(var b=new SolidBrush(desktop.GetPixel(px,py)))e.Graphics.FillRectangle(b,x+10+(dx+4)*10,y+10+(dy+4)*10,10,10);}e.Graphics.DrawRectangle(Pens.White,x+50,y+50,10,10);Color c=desktop.GetPixel(sample.X,sample.Y);using(var b=new SolidBrush(c))e.Graphics.FillRectangle(b,x+116,y+10,94,46);TextRenderer.DrawText(e.Graphics,Hex(c),Font,new Point(x+114,y+64),Ink);TextRenderer.DrawText(e.Graphics,"Click to pick · Esc to cancel",Font,new Point(x+10,y+116),Ink);}
}
